import{_ as t,o as a,c as s,a4 as n}from"./chunks/framework.DHNVigYl.js";const q=JSON.parse('{"title":"Adding decoders","description":"","frontmatter":{},"headers":[],"relativePath":"participate/adding-decoders.md","filePath":"participate/adding-decoders.md","lastUpdated":1786732983000}'),o={name:"participate/adding-decoders.md"};function i(r,e,u,p,d,l){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="adding-decoders" tabindex="-1">Adding decoders <a class="header-anchor" href="#adding-decoders" aria-label="Permalink to &quot;Adding decoders&quot;">​</a></h1><p>Adding your device protocol to Theengs Decoder enables to increase interoperability and to create new use cases with your device. Below you will find some guidance to do that.</p><p>You can do a pull request directly to the <a href="https://github.com/theengs/decoder" target="_blank" rel="noreferrer">Repository</a>.</p><h1 id="adding-device-decoding" tabindex="-1">Adding device decoding <a class="header-anchor" href="#adding-device-decoding" aria-label="Permalink to &quot;Adding device decoding&quot;">​</a></h1><p>Device decode specifications are located in a json file, example <a href="https://github.com/theengs/decoder/blob/development/src/devices/HHCCJCY01HHCC_json.h" target="_blank" rel="noreferrer">HHCCJCY01HHCC_json.h</a>. The format is:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>R&quot;&quot;&quot;&quot;(</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>   &quot;brand&quot;:&quot;Xiaomi&quot;,</span></span>
<span class="line"><span>   &quot;model&quot;:&quot;miflora&quot;,</span></span>
<span class="line"><span>   &quot;model_id&quot;:&quot;HHCCJCY01HHCC&quot;,</span></span>
<span class="line"><span>   &quot;condition&quot;:[&quot;servicedata&quot;, &quot;contain&quot;, &quot;209800&quot;],</span></span>
<span class="line"><span>   &quot;properties&quot;:{</span></span>
<span class="line"><span>      &quot;tempc&quot;:{</span></span>
<span class="line"><span>         &quot;condition&quot;:[&quot;servicedata&quot;, 25, &quot;4&quot;],</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;servicedata&quot;, 30, 4, true],</span></span>
<span class="line"><span>         &quot;post_proc&quot;:[&quot;/&quot;, 10]</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;moi&quot;:{</span></span>
<span class="line"><span>         &quot;condition&quot;:[&quot;servicedata&quot;, 25, &quot;8&quot;],</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;servicedata&quot;, 30, 2, false]</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;lux&quot;:{</span></span>
<span class="line"><span>         &quot;condition&quot;:[&quot;servicedata&quot;, 25, &quot;7&quot;],</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;servicedata&quot;, 30, 6, true]</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;fer&quot;:{</span></span>
<span class="line"><span>         &quot;condition&quot;:[&quot;servicedata&quot;, 25, &quot;9&quot;],</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;servicedata&quot;, 30, 4, true]</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>})&quot;&quot;&quot;&quot;,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br></div></div><p>Each device must provide a <code>brand</code>, <code>model</code>, <code>model_id</code>, <code>condition</code>, and <code>properties</code>.</p><ul><li><code>brand</code> = brand name of the device.</li><li><code>model</code> = model name of the device.</li><li><code>model_id</code> = model id number of the device.</li></ul><h3 id="tag-property" tabindex="-1">Tag property <a class="header-anchor" href="#tag-property" aria-label="Permalink to &quot;Tag property&quot;">​</a></h3><p>Each device should also have an encoded <strong>tag</strong> property to, at the minimum, define the device type for a decoder, and additionally define other descriptive properties to be published. This enables projects to adjust their display and scanning behaviour accordingly.</p><table><thead><tr><th colspan="3">tag encoding</th></tr></thead><tbody><tr><td rowspan="24">Byte[0]</td><td rowspan="24">Device Type &gt; &quot;type&quot;:</td><td>0 - Reserved</td></tr><tr><td>1 - THB - temperature, humidity, battery</td></tr><tr><td>2 - THBX - temperature, humidity, battery, extras</td></tr><tr><td>3 - BBQ - temperatures with several probes</td></tr><tr><td>4 - CTMO - contact and/or motion sensors</td></tr><tr><td>5 - SCALE - weight scales</td></tr><tr><td>6 - BCON - iBeacon protocol</td></tr><tr><td>7 - ACEL - acceleration</td></tr><tr><td>8 - BATT - battery</td></tr><tr><td>9 - PLANT - plant sensors</td></tr><tr><td>10 - TIRE - tire pressure monitoring system</td></tr><tr><td>11 - BODY - health monitoring devices</td></tr><tr><td>12 - ENRG - energy monitoring devices</td></tr><tr><td>13 - WCVR - window covering devices</td></tr><tr><td>14 - ACTR - ON/OFF actuators</td></tr><tr><td>15 - AIR - air environmental monitoring devices</td></tr><tr><td>16 - TRACK - bluetooth tracker</td></tr><tr><td>17 - BTN - button</td></tr><tr><td>18 - AUDIO - audio devices</td></tr><tr><td>19 - WIND - wind speed anemometers</td></tr><tr><td>20 - ENRG - energy producing, monitoring and storing devices</td></tr><tr><td>20-253 - Reserved for future use</td></tr><tr><td>254 - RMAC - known random MAC address devices</td></tr><tr><td>255 - UNIQ - unique devices</td></tr><tr><td rowspan="8">Byte[1]</td><td rowspan="8">Additional properties</td><td>Bits[7] - Reserved for future use</td></tr><tr><td>Bit[5] Battery and/or voltage are primary properties &gt; &quot;bvpp&quot;:</td></tr><tr><td>Bit[5] Devices/actuators which are controllable &gt; &quot;ctrl&quot;:</td></tr><tr><td>Bit[4] Potential RMAC device - if not defined with Identity MAC and IRK in Theengs Gateway &gt; &quot;prmac&quot;:</td></tr><tr><td>Bit[3] Device discoverable as a device tracker &gt; &quot;track&quot;:</td></tr><tr><td>Bit[2] Requires continuous scanning &gt; &quot;cont&quot;:</td></tr><tr><td>Bit[1] Requires active scanning &gt; &quot;acts&quot;:</td></tr><tr><td>Bit[0] Is NOT Company ID compliant &gt; &quot;cidc&quot;:</td></tr><tr><td rowspan="3">Byte[2]</td><td rowspan="3">Encryption Model &gt; &quot;encr&quot;:</td><td>1 - LYWSD03MMC PVVX</td></tr><tr><td>2 - BTHome v2</td></tr><tr><td>3 - Victron Energy</td></tr></tbody></table><p><strong>cidc</strong> - Whenever a decoder is based on &quot;manufacturerdata&quot; and the first bytes do not comply with the <a href="https://www.bluetooth.com/specifications/assigned-numbers/company-identifiers/" target="_blank" rel="noreferrer">Bluetooth SIG&#39;s company identifier convention</a>, this should be set to 1/true, to then produce &quot;cidc&quot;:false in the published message.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   &quot;brand&quot;:&quot;Otio/BeeWi&quot;,</span></span>
<span class="line"><span>   &quot;model&quot;:&quot;Door &amp; Window Sensor&quot;,</span></span>
<span class="line"><span>   &quot;model_id&quot;:&quot;BSDOO&quot;,</span></span>
<span class="line"><span>   &quot;tag&quot;:&quot;0405&quot;,</span></span>
<span class="line"><span>   …</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>will have <code>… &quot;type&quot;:&quot;CTMO&quot;,&quot;cidc&quot;:false,&quot;cont&quot;:true …</code> in the published message.</p><h3 id="condition" tabindex="-1">Condition <a class="header-anchor" href="#condition" aria-label="Permalink to &quot;Condition&quot;">​</a></h3><p><code>condition</code> is a JSON array, which must contain as the first parameter, the data source to test for the condition. Valid inputs are:</p><ul><li>&quot;servicedata&quot;</li><li>&quot;manufacturerdata&quot;</li><li>&quot;name&quot;</li><li>&quot;uuid&quot;</li></ul><p>The second parameter is variable. If required, further qualification can be made by setting a conditional data length in the case of &quot;servicedata&quot; or &quot;manufacturerdata&quot; as the first condition. This is an operator in the form of <code>&quot;&gt;&quot; , &quot;&gt;=&quot; , &quot;=&quot; , &quot;&lt;&quot; , &quot;&lt;=&quot;</code> followed by the third parameter being a numeric value that specifies the length of the data to accept. If no data length is defined the second parameter must indicate how the data should be tested. Valid inputs are:</p><ul><li>&quot;contain&quot; tests if the specified value (see below) exists the data source</li><li>&quot;index&quot; tests if the specified value exists at the index location (see below) in the data source</li><li>&quot;mac@index&quot; tests if the device&#39;s MAC address exists at the index location (see below) in the data source</li><li>&quot;revmac@index&quot; tests if the device&#39;s MAC address exists octet-reversed at the index location (see below) in the data source</li></ul><div class="warning custom-block"><p class="custom-block-title">Note</p><p>For compatibility of a decoder for running successfully on an OS which masks the real MAC addresses of devices by generic uuids, like macOS and iOS, an alternative model condition with the name &quot;conditionnomac&quot; needs to be defined in addition to &quot;condition&quot; if the latter contains &quot;mac@index&quot; or &quot;revmac@index&quot;.</p></div><p>Examples: <code>&quot;condition&quot;:[&quot;servicedata&quot;, &quot;index&quot;, 0, &quot;0804&quot;</code> -- no data length check <code>&quot;condition&quot;:[&quot;servicedata&quot;, &quot;&gt;=&quot;, 40, &quot;index&quot;, 0, &quot;0804&quot;</code> -- data length must be equal to or greater than 40 bytes</p><p>The third parameter (fifth if data length is specified) can be either the index value or the data value to find. If the second (fourth if data length specified) parameter is <code>contain</code>, the next parameter should be the value to look for in the data source. If the second (fourth if data length specified) parameter is <code>index</code>, <code>mac@index</code> or <code>revmac@index</code> the next parameter should be the location in the data source to look for the value.</p><p><code>condition</code> can have multiple conditions chained together using &quot;|&quot; and &quot;&amp;&quot; between them.<br> For example: <code>&quot;condition&quot;:[&quot;servicedata&quot;, &quot;index&quot;, 0, &quot;0804&quot;, &quot;|&quot;, &quot;servicedata&quot;, &quot;index&quot;, 0, &quot;8804&quot;]</code><br> This will match if the service data at index 0 is &quot;0804&quot; <code>OR</code> &quot;8804&quot;.</p><p><code>condition</code> can contain JSON arrays that can be processed separately. This allows for nesting of detection tests such as:<br><code>&quot;condition&quot;: [[&quot;servicedata&quot;, &quot;index&quot;, 0, &quot;1234&quot;, &quot;&amp;&quot; &quot;servicedata&quot;, &quot;index&quot;, 5, &quot;5678&quot;], &quot;|&quot;, &quot;servicedata&quot;, &quot;index&quot;, 30, &quot;abcd&quot;]</code><br> This will result in a positive detection if the service data at index <code>0</code> == <code>0x1234</code> and the service data at index <code>5</code> == <code>0x5678</code>, otherwise, if the service data at index <code>30</code> == <code>0xabcd</code>, the result will also be positive.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Nesting is discouraged from use wherever possible as the recursive nature may cause stack overflowing in some circumstances. It should only be used if absolutely necessary, as in the above example. If all the conditions in an array bracket are chained with &quot;|&quot;, as in <code>&quot;condition&quot;: [[&quot;servicedata&quot;, &quot;index&quot;, 0, &quot;abcd&quot;, &quot;|&quot;, &quot;servicedata&quot;, &quot;index&quot;, 0, &quot;efef&quot;], &quot;&amp;&quot;, &quot;servicedata&quot;, &quot;index&quot;, 5, &quot;1212&quot;]</code> this could be re-written as <code>&quot;condition&quot;: [&quot;servicedata&quot;, &quot;index&quot;, 0, &quot;abcd&quot;, &quot;|&quot;, &quot;servicedata&quot;, &quot;index&quot;, 0, &quot;efef&quot;, &quot;&amp;&quot;, &quot;servicedata&quot;, &quot;index&quot;, 5, &quot;1212&quot;]</code><br> making sure the additional AND condition is at the end. This has the same result, without nesting.</p></div><p><code>condition</code> NOT(!) testing; Anytime a condition test value is preceded by a &quot;!&quot;, the inverse of the result will be used to determine the result.<br> Example: \`&quot;condition&quot;: [&quot;servicedata&quot;, &quot;index&quot;, 30, &quot;!&quot;, &quot;abcd&quot;, &quot;&amp;&quot;, &quot;servicedata&quot;, &quot;index&quot;, 0, &quot;1234&quot;]<br> If the value of the service data at index 30 is not 0xabcd and the data at index 0 is 0x1234, the result is a positive detection.</p><p><code>condition</code> &quot;no-mfgdata&quot;; This single argument condition allows to test for the non-existence of manufacturerdata in the received advertising data.</p><h3 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h3><p>Properties is a nested JSON object containing one or more JSON objects. In the example above it looks like:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> &quot;properties&quot;:{</span></span>
<span class="line"><span>      &quot;tempc&quot;:{</span></span>
<span class="line"><span>         &quot;condition&quot;:[&quot;servicedata&quot;, 25, &quot;4&quot;],</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;servicedata&quot;, 30, 4, true],</span></span>
<span class="line"><span>         &quot;post_proc&quot;:[&quot;/&quot;, 10]</span></span>
<span class="line"><span>      },</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Here we have a single property that defines a value that we want to decode. The key &quot;tempc&quot; will be used as the key in the JsonObject provided when <code>decodeBLEJson(JsonObject)</code> is called. &quot;tempc&quot; in this example is another JSON object that has an (optional, explained below) <code>condition</code>, <code>decoder</code>, and <code>post_proc</code>.</p><p><code>condition</code> is a JSON array. The first parameter defines the data source of the condition to test and must be one of:</p><ul><li>&quot;servicedata&quot;</li><li>&quot;manufacturerdata&quot;</li><li>&quot;name&quot;</li></ul><p>The second parameter is the index of the data source to look for the value. For a <code>&quot;name&quot;</code> comparison the second parameter is either <code>&quot;contain&quot;</code> or <code>&quot;not_contain&quot;</code>.</p><p>Then the third parameter is the value to test for, or in case of the <code>&quot;name&quot;</code> comparison the string to compare the device name to.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> &quot;properties&quot;:{</span></span>
<span class="line"><span>      &quot;hum&quot;:{</span></span>
<span class="line"><span>         &quot;condition&quot;:[&quot;name&quot;, &quot;not_contain&quot;, &quot;GV5108&quot;],</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;manufacturerdata&quot;, 8, 6, false, false],</span></span>
<span class="line"><span>         &quot;post_proc&quot;:[&quot;&amp;&quot;, 8388607, &quot;%&quot;, 1000, &quot;/&quot;, 10]</span></span>
<span class="line"><span>      },</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>If a direct binary bit evaluation encoded in a hex digit is desired the third parameter is <code>&quot;bit&quot;</code>, the fourth parameter the bit position from <code>3-0</code> and the fifth parameter the bit state <code>0</code> or <code>1</code>.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> &quot;properties&quot;:{</span></span>
<span class="line"><span>      &quot;hum&quot;:{</span></span>
<span class="line"><span>         &quot;condition&quot;:[&quot;servicedata&quot;, 10, &quot;bit&quot;, 3, 0],</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;servicedata&quot;, 10, 2, false, false]</span></span>
<span class="line"><span>      },</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>The second parameter can also be an operator in the form of <code>&quot;&gt;&quot; , &quot;&gt;=&quot; , &quot;=&quot; , &quot;&lt;&quot; , &quot;&lt;=&quot;</code>, then followed by the third parameter being a numeric value that specifies the length of the data to accept for evaluation of the first parameter.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> &quot;properties&quot;:{</span></span>
<span class="line"><span>      &quot;tempc&quot;:{</span></span>
<span class="line"><span>         &quot;condition&quot;:[&quot;manufacturerdata&quot;, &quot;=&quot;, 40],</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;manufacturerdata&quot;, 24, 4, true]</span></span>
<span class="line"><span>      },</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>If the condition is met the data will be decoded and added to the JsonObject.</p><p><code>condition</code> can contain JSON arrays that can be processed separately. This allows for nesting of detection tests such as:<br><code>&quot;condition&quot;: [[&quot;servicedata&quot;, 25, &quot;4&quot;, &quot;&amp;&quot; &quot;servicedata&quot;, 26, &quot;5&quot;], &quot;|&quot;, &quot;servicedata&quot;, 30, &quot;abcd&quot;]</code><br> This will result in a positive detection if the service data at index <code>25</code> == <code>4</code> and the service data at index <code>26</code> == <code>5</code>, otherwise, if the service data at index <code>30</code> == <code>0xabcd</code>, the result will also be positive.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Nesting is discouraged from use wherever possible as the recursive nature may cause stack overflowing in some circumstances. It should only be used if absolutely necessary, as in the above example. If all the conditions in an array bracket are chained with &quot;|&quot;, as in <code>&quot;condition&quot;: [[&quot;servicedata&quot;, 20, &quot;5&quot;, &quot;|&quot;, &quot;servicedata&quot;, 20, &quot;6&quot;], &quot;&amp;&quot;, &quot;servicedata&quot;, 30, &quot;a&quot;]</code> this could be re-written as <code>&quot;condition&quot;: [&quot;servicedata&quot;, 20 , &quot;5&quot;, &quot;|&quot;, &quot;servicedata&quot;, 20, &quot;6&quot;, &quot;&amp;&quot;, &quot;servicedata&quot;, 30, &quot;a&quot;]</code><br> making sure the additional AND condition is at the end. This has the same result, without nesting.</p></div><p>Property conditions also allow for a NOT comparison, as in</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> &quot;properties&quot;:{</span></span>
<span class="line"><span>      &quot;tempc&quot;:{</span></span>
<span class="line"><span>         &quot;condition&quot;:[&quot;manufacturerdata&quot;, 24, &quot;!&quot;, &quot;ffff&quot;],</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;manufacturerdata&quot;, 24, 4, true, false],</span></span>
<span class="line"><span>         &quot;post_proc&quot;:[&quot;/&quot;, 10]</span></span>
<span class="line"><span>      },</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>where then the fourth parameter is the value to test for.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>The NOT comparison is case sensitive! Therefore any NOT comparisons should be defined in lower case, as this is the format in which devices&#39; &quot;servicedata&quot; and &quot;manufacturerdata&quot; are being reported.</p></div><p><code>decoder</code> is a JSON array that specifies the decoder function and parameters to decode the value. The first parameter is the name of the function to call, The available functions are:</p><ul><li>&quot;value_from_hex_data&quot; - converts the hex string value into an <code>integer</code> or <code>double</code> type.</li><li>&quot;bf_value_from_hex_data&quot; - converts the (binary fraction) hex string value into a <code>double</code> type. This should be used when the hex data is represented in the format of <code>XX.XX</code>. For example: when <code>0x1a1e</code> should output 26.30.</li><li>&quot;string_from_hex_data&quot; - converts the hex value to a string type.</li><li>&quot;ascii_from_hex_data&quot; - converts the hex value to ASCII text.</li><li>&quot;static_value&quot; - sets the value to the static value specified if the condition is met.</li><li>&quot;bit_static_value&quot; - sets the value to either one of two given values, depending on the evaluated binary bit.</li></ul><p>The other parameters for the first three functions are:</p><ul><li>&quot;servicedata&quot; or &quot;manufacturerdata&quot; Extract the value from the specified data.</li><li>24, The index of the data source where the value exists.</li><li>4, The length of the data in bytes (characters in the string). and additional boolean parameters applicable to the first two functions:</li><li>true/false, If the value in the data source should have its endianness reversed before converting.</li><li>(optional)true/false, Sets if the resulting value can be a negative number. Defaults to true when omitted.</li><li>(optional)false/true, Sets if the &quot;value_from_hex_data&quot; decoding result is a <code>float</code> instead of an <code>integer</code> type. Defaults to false when omitted.</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> &quot;properties&quot;:{</span></span>
<span class="line"><span>      &quot;unit&quot;:{</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;bit_static_value&quot;, &quot;servicedata&quot;, 1, 0, &quot;kg&quot;, &quot;lb&quot;]</span></span>
<span class="line"><span>      },</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>The parameters for the &quot;bit_static_value&quot; function are:</p><ul><li>&quot;servicedata&quot; or &quot;manufacturerdata&quot; - extract the value from the specified data.</li><li>1, the index of the data source where the value exists.</li><li>0, the bit position from <code>3-0</code>.</li><li>The return value for bit state <code>0</code>.</li><li>The return value for bit state <code>1</code>.</li></ul><p><code>post_proc</code> This specifies any post processing of the resulting decoded value. This is a JSON array that should be written in the order that the operation order is desired. In the simple example the first parameter is the &quot;/&quot; divide operation and the second parameter (10) is the value to divide the result by. Multiple operations can be chained together in this array to perform more complex calculations.</p><p>Valid operations are:</p><ul><li>&quot;/&quot; divide</li><li>&quot;*&quot; multiply</li><li>&quot;+&quot; add</li><li>&quot;-&quot; subtract</li><li>&quot;±&quot; signed conditional add or subtract</li><li>&quot;%&quot; modulo</li><li>&quot;&lt;&quot; shift left</li><li>&quot;&gt;&quot; shift right</li><li>&quot;!&quot; Not (invert), useful for bool types</li><li>&quot;&amp;&quot; Logical AND the values</li><li>&quot;^&quot; Logical XOR the values</li><li>&quot;min&quot; the minimum allowed value</li><li>&quot;max&quot; the maximum allowed value</li><li>&quot;abs&quot; absolute value</li></ul><p><code>lookup</code> This specifies a lookup table for any decoded &quot;string_from_hex_data&quot; string. If the string is defined in the table its related string will be assigned to the property. If no matching hex string is present the property is defined as not decoded.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> &quot;state&quot;:{</span></span>
<span class="line"><span>    &quot;decoder&quot;:[&quot;string_from_hex_data&quot;, &quot;manufacturerdata&quot;, 10, 2],</span></span>
<span class="line"><span>    &quot;lookup&quot;:[&quot;01&quot;, &quot;initialising&quot;, </span></span>
<span class="line"><span>              &quot;02&quot;, &quot;idle&quot;, </span></span>
<span class="line"><span>              &quot;03&quot;, &quot;running&quot;, </span></span>
<span class="line"><span>              &quot;04&quot;, &quot;charging&quot;, </span></span>
<span class="line"><span>              &quot;73&quot;, &quot;sleeping&quot;]</span></span>
<span class="line"><span> },</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h4 id="special-property-cal" tabindex="-1">Special property .cal <a class="header-anchor" href="#special-property-cal" aria-label="Permalink to &quot;Special property .cal&quot;">​</a></h4><p>.cal is a special property that can extracted from the provided data and used in calculations of other properties following it&#39;s definition. For example:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;properties&quot;:{</span></span>
<span class="line"><span>      &quot;.cal&quot;:{</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;manufacturerdata&quot;, 16, 4, true],</span></span>
<span class="line"><span>         &quot;post_proc&quot;:[&quot;&amp;&quot;, 16383]</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;power&quot;:{</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;value_from_hex_data&quot;, &quot;manufacturerdata&quot;, 4, 4, true],</span></span>
<span class="line"><span>         &quot;post_proc&quot;:[&quot;/&quot;, &quot;.cal&quot;, &quot;*&quot;, 60000]</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>   }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>Here the calculation value extracted first from the data stream and used by the next property to calculate the data value.</p><h4 id="special-property-mac" tabindex="-1">Special property &quot;mac&quot; <a class="header-anchor" href="#special-property-mac" aria-label="Permalink to &quot;Special property &quot;mac&quot;&quot;">​</a></h4><p>The &quot;mac&quot; property contains a device&#39;s MAC address if this is contained in the broadcast service- or manufacturerdata, with either forward or reversed octet order.</p><p>In such cases the &quot;mac&quot; property should be included in the decoder, so that these devices can have their proper MAC address assigned on iOS or macOS, which usually masks these with generic uuids.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;properties&quot;:{</span></span>
<span class="line"><span>      &quot;mac&quot;:{</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;mac_from_hex_data&quot;, &quot;servicedata&quot;, 4]</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      … or</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      &quot;mac&quot;:{</span></span>
<span class="line"><span>         &quot;decoder&quot;:[&quot;revmac_from_hex_data&quot;, &quot;servicedata&quot;, 4]</span></span>
<span class="line"><span>      }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h1 id="checking-and-fixing-your-changes" tabindex="-1">Checking and fixing your changes <a class="header-anchor" href="#checking-and-fixing-your-changes" aria-label="Permalink to &quot;Checking and fixing your changes&quot;">​</a></h1><p>You can use a script to check whether your raw JSON strings correspond to the escaped string value in the line before. Run the script as:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python scripts/check_decoder.py src/devices/NAMEOFDEVICE.h</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>You can also install <a href="https://pre-commit.com" target="_blank" rel="noreferrer">pre-commit</a> to run this check every time you commit a file change:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install pre-commit</span></span>
<span class="line"><span>pre-commit install</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The last command should be run in the root directory of the decoder repository.</p><p>If you&#39;re using <a href="https://code.visualstudio.com" target="_blank" rel="noreferrer">Visual Studio Code</a>, you can install the <a href="https://marketplace.visualstudio.com/items?itemName=elagil.pre-commit-helper" target="_blank" rel="noreferrer">pre-commit extension</a>. After this, when you have a decoder file open, just open the command palette with Ctrl+Shift+P and choose <strong>pre-commit run (current file)</strong> to check and fix its JSON strings.</p><p>Tip: if you just declare a JSON string with an empty string, such as:</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _SBBT_002C_json </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then the script automatically copies the following raw string in the comment to fill the empty string in the previous line, with all double quotes escaped correctly.</p>`,77)])])}const h=t(o,[["render",i]]);export{q as __pageData,h as default};
